fixtures = []
for label, scenarios in [('scam', SCAMS), ('benign', BENIGN)]:
    for scenario_index, scenario in enumerate(scenarios):
        group, title = scenario[:2]
        intro, phrases = (scenario[2], scenario[3]) if label == 'scam' else ('Hello, thanks for taking my call.', scenario[2])
        for wording, phrase in enumerate(phrases, 1):
            for presentation in ['natural', 'lowercase', 'uppercase', 'single-segment']:
                lines = [intro, phrase]
                if presentation == 'lowercase': lines = [x.lower() for x in lines]
                if presentation == 'uppercase': lines = [x.upper() for x in lines]
                if presentation == 'single-segment': lines = [' '.join(lines)]
                fixtures.append(dict(id=1001 + len(fixtures), group=group, title=f'{title} / wording {wording} / {presentation}', label=label, lines=lines, expected='Trigger' if label == 'scam' else 'Stays quiet', expected_trigger=label == 'scam', scenario_id=f'{label}-{scenario_index + 1:02}', presentation=presentation, note='Active caller demand or coercion.' if label == 'scam' else 'No active coercive payment or credential demand; do not intervene.'))
assert len(fixtures) == 1000
assert len({tuple(f['lines']) for f in fixtures}) == 1000
Path(__file__).resolve().parents[1].joinpath('judging_fixtures_1000.json').write_text(json.dumps(fixtures, indent=2) + '\n')
